#include <vector>
#include <algorithm>

class Solution {
public:
    int longestSubsequenceAfterOneReplacement(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return n;
        std::vector<int> left(n, 1), right(n, 1);
        for (int i = 1; i < n; ++i) {
            if (nums[i] > nums[i - 1]) left[i] = left[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; --i) {
            if (nums[i] < nums[i + 1]) right[i] = right[i + 1] + 1;
        }
        int best = 0;
        for (int v : left) best = std::max(best, v);
        for (int i = 0; i < n; ++i) {
            if (i > 0) best = std::max(best, left[i - 1] + 1);
            if (i < n - 1) best = std::max(best, right[i + 1] + 1);
            if (i > 0 && i < n - 1 && (long long)nums[i + 1] - nums[i - 1] >= 2) {
                best = std::max(best, left[i - 1] + 1 + right[i + 1]);
            }
        }
        return best;
    }
};

class Solution {
    public int longestSubsequenceAfterOneReplacement(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;
        int[] left = new int[n];
        int[] right = new int[n];
        java.util.Arrays.fill(left, 1);
        java.util.Arrays.fill(right, 1);
        for (int i = 1; i < n; i++) {
            if (nums[i] > nums[i - 1]) left[i] = left[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] < nums[i + 1]) right[i] = right[i + 1] + 1;
        }
        int best = 0;
        for (int v : left) best = Math.max(best, v);
        for (int i = 0; i < n; i++) {
            if (i > 0) best = Math.max(best, left[i - 1] + 1);
            if (i < n - 1) best = Math.max(best, right[i + 1] + 1);
            if (i > 0 && i < n - 1 && (long)nums[i + 1] - nums[i - 1] >= 2) {
                best = Math.max(best, left[i - 1] + 1 + right[i + 1]);
            }
        }
        return best;
    }
}

